import {opportunity} from './events.mjs';
import {levelOf,incomeAt} from './levels.mjs';
import {netWorth,financialSnapshot,monthlyPayment} from './engine.mjs';
const money=n=>(n<0?'−':'')+'$'+Math.abs(n).toLocaleString('en-US',{maximumFractionDigits:0});
export function financialModel(s){const l=levelOf(s),f=financialSnapshot(s),finished=s.phase==='finished',month=finished?null:Math.min(12,s.month+1),income=month?incomeAt(s,month):0,living=month?l.living:0,pressure=month?(l.pressure?.[month]||0):0,installments=month?monthlyPayment(s):0,due=living+pressure+installments,liquid=f.cash+f.reserve,after=liquid+income-due,cashAfter=f.cash+income-due,reserveMonths=f.reserve/l.living;return {f,finished,month,income,living,pressure,installments,due,liquid,after,cashAfter,reserveMonths,tone:finished&&s.shortfall>0||after<0?'danger':reserveMonths<3||cashAfter<0?'warning':'stable'};}
export function financialDashboard(s,lang='vi'){const vi=lang==='vi',t=(a,b)=>vi?a:b,m=financialModel(s),f=m.f,l=levelOf(s),parts=[['cash',t('Tiền mặt','Cash'),f.cash],['reserve',t('Dự phòng','Reserve'),f.reserve],['liquid',t('Đầu tư bán được','Sellable investments'),f.liquidAssets],['locked',t('Vốn đang khóa','Locked capital'),f.lockedAssets]],gross=parts.reduce((n,p)=>n+p[2],0),message=m.finished?(s.shortfall>0?t('Đã thiếu khả năng thanh toán','An obligation could not be paid'):t('Chặng đã kết thúc — xem lại quyết định','Stage complete — review your decisions')):m.after<0?t('Nguy cơ thiếu tiền ngay tháng tới','Next month’s known payments are underfunded'):m.cashAfter<0?t('Tháng tới có thể phải dùng dự phòng','Next month may draw on your reserve'):m.reserveMonths<1?t('Dự phòng dưới 1 tháng sinh hoạt','Reserve below one month of living costs'):m.reserveMonths<3?t('Dự phòng chưa đủ 3 tháng sinh hoạt','Reserve below three months of living costs'):t('Đủ cho nghĩa vụ đã biết — vẫn cần dự phòng rủi ro','Known payments covered — unexpected risks still matter');
return `<section class="finance-dashboard ${m.tone}" aria-label="${t('Tình hình tài chính cập nhật','Updated financial position')}"><div class="finance-heading"><div><p class="eyebrow">${t('BẢNG ĐIỀU KHIỂN TÀI CHÍNH','FINANCIAL CONTROL PANEL')}</p><h2>${t('Nhìn rõ tiền. Trước khi quyết định.','See your money. Before deciding.')}</h2></div><span>${t('Cập nhật sau mỗi quyết định','Updates after every decision')}</span></div><div class="finance-alert" role="status"><b>${message}</b><span>${t('Dự phòng','Reserve')}: ${m.reserveMonths.toFixed(1)} ${t('tháng sinh hoạt','months of living costs')} · ${t('Nợ còn lại','Outstanding debt')}: ${money(f.debt)}</span></div><div class="finance-columns"><div class="capital-panel"><h3>${t('Tiền của bạn đang ở đâu?','Where is your money?')}</h3><div class="capital-bar" role="img" aria-label="${parts.map(p=>p[1]+': '+money(p[2])).join('; ')}">${parts.filter(p=>p[2]>0).map(p=>`<i class="capital-${p[0]}" style="flex:${p[2]/(gross||1)}"></i>`).join('')}</div><div class="capital-legend">${parts.map(p=>`<div><i class="capital-${p[0]}"></i><span>${p[1]}</span><b>${money(p[2])}</b></div>`).join('')}</div><p class="finance-note">${t('Tiền có thể dùng ngay = tiền mặt + dự phòng. Đầu tư bán được vẫn phải bán mới có tiền; vốn khóa không trả hóa đơn được. Nợ được trừ khi tính tài sản ròng.','Immediately available money = cash + reserve. Sellable investments still require a sale; locked capital cannot pay bills. Debt is deducted from net worth.')}</p></div><div class="obligation-panel"><h3>${m.finished?t('Kết quả cuối chặng','End-of-stage position'):t('Nghĩa vụ đã biết tháng','Known obligations — month')+' '+m.month}</h3>${m.finished?`<p>${t('Tài sản ròng','Net worth')}: <b>${money(netWorth(s))}</b></p><p>${t('Khoản chưa thanh toán','Unpaid obligations')}: <b>${money(s.shortfall)}</b></p>`:`<dl><div><dt>${t('Tiền dùng ngay hiện có','Available now')}</dt><dd>${money(m.liquid)}</dd></div><div><dt>+ ${t('Lương dự kiến','Expected salary')}</dt><dd>${money(m.income)}</dd></div><div><dt>− ${t('Sinh hoạt','Living costs')}</dt><dd>${money(m.living)}</dd></div><div><dt>− ${t('Chi bắt buộc theo cấp','Level charges')}</dt><dd>${money(m.pressure)}</dd></div><div><dt>− ${t('Trả góp đến hạn','Due installments')}</dt><dd>${money(m.installments)}</dd></div><div class="${m.income-m.due<0?'flow-negative':''}"><dt>${t('Dòng tiền thuần đã biết','Known net cash flow')}</dt><dd>${money(m.income-m.due)}</dd></div><div class="obligation-total"><dt>${t('Còn lại sau nghĩa vụ','After known obligations')}</dt><dd>${money(m.after)}</dd></div></dl><p class="finance-note">${t('Chưa trừ chi phí bất ngờ, chưa cộng thu nhập làm thêm, tiền chia từ đầu tư hoặc lợi nhuận chưa chắc có. Đây không phải số tiền có thể tiêu hết an toàn.','Excludes unexpected costs and uncertain side income, investment distributions or gains. This is not an amount you can safely spend in full.')}</p>`}</div></div>${financeChart(s,lang)}<p class="finance-note">${t('Dữ liệu game giả lập, cập nhật theo quyết định; không phải giá thị trường trực tiếp.','Simulated game data updated by decisions; not a live market-price feed.')}</p></section>`;}
function financeChart(s,lang){const vi=lang==='vi',l=levelOf(s),liquid=new Map([[0,l.cash+l.reserve]]),wealth=new Map([[0,l.cash+l.reserve]]);for(const r of [...s.history].reverse()){if(r.finances)liquid.set(r.month,r.finances.cash+r.finances.reserve);if(Number.isFinite(r.netWorth))wealth.set(r.month,r.netWorth);}liquid.set(s.month,s.cash+s.reserve);wealth.set(s.month,netWorth(s));const values=[...liquid.values(),...wealth.values()],low=Math.min(0,...values),high=Math.max(1,...values)*1.08,x=n=>54+n/12*676,y=n=>168-(n-low)/(high-low)*140,points=map=>[...map].sort((a,b)=>a[0]-b[0]).map(([a,b])=>`${x(a).toFixed(1)},${y(b).toFixed(1)}`).join(' ');return `<div class="finance-trend"><h3>${vi?'Diễn biến qua từng tháng':'Your monthly trajectory'}</h3><svg viewBox="0 0 760 204" role="img" aria-label="${vi?'Đường tiền dùng ngay và tài sản ròng qua các mốc đã lưu':'Available money and net worth across recorded checkpoints'}"><line x1="54" x2="730" y1="168" y2="168" stroke="#bdcbbf"/><line x1="54" x2="730" y1="98" y2="98" stroke="#e1e8df"/><text x="3" y="34">${money(high)}</text><text x="3" y="168">${money(low)}</text>${[0,3,6,9,12].map(n=>`<text x="${x(n)}" y="194" text-anchor="middle">${n}</text>`).join('')}<polyline points="${points(wealth)}" fill="none" stroke="#8570a6" stroke-width="3" stroke-dasharray="6 4"/><polyline points="${points(liquid)}" fill="none" stroke="#15765d" stroke-width="4"/><circle cx="${x(s.month)}" cy="${y(s.cash+s.reserve)}" r="5" fill="#15765d"/><circle cx="${x(s.month)}" cy="${y(netWorth(s))}" r="4" fill="#8570a6"/></svg><div class="trend-legend"><span>● ${vi?'Tiền dùng ngay (mặt + dự phòng)':'Available money (cash + reserve)'}</span><span>┄ ${vi?'Tài sản ròng':'Net worth'}</span><small>${vi?'Trục ngang: tháng · Nối các mốc đã ghi nhận; lịch sử thanh khoản chi tiết bắt đầu từ bản này.':'Horizontal axis: month · Lines connect recorded checkpoints; detailed liquidity history begins with this version.'}</small></div></div>`;}

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function portfolioDetails(s,lang='vi'){
 const vi=lang==='vi',t=(a,b)=>vi?a:b,groups=new Map(),latest=s.pending?.monthly?s.pending:s.last;
 for(const p of s.positions){if(p.value<=0&&p.debt<=0)continue;const g=groups.get(p.id)||{id:p.id,value:0,debt:0,payment:0,locked:p.locked};g.value+=p.value;g.debt+=p.debt;g.payment+=Math.min(p.payment,p.debt);groups.set(p.id,g);}
 return `<section class="holdings-panel" aria-label="${t('Danh mục đầu tư chi tiết','Detailed investment holdings')}"><div class="holdings-title"><h3>${t('Danh mục đã đầu tư','Your investments')}</h3><span>${groups.size} ${t('khoản','holdings')}</span></div>${groups.size?`<div class="holdings-list">${[...groups.values()].map(p=>{const o=opportunity(p.id),changes=[...(latest?.monthly?.portfolio?.changes||[]),...(latest?.changes||[])].filter(x=>x.id===p.id),change=changes.reduce((n,x)=>n+x.change,0),cash=(latest?.monthly?.portfolio?.changes||[]).filter(x=>x.id===p.id).reduce((n,x)=>n+x.cash,0);return `<article class="holding"><div class="holding-head"><strong>${esc(p.id==='legacy'?t('Khoản đầu tư đã lưu','Saved investment'):o?.[lang]?.[0]||p.id)}</strong><b>${money(p.value)}</b></div><div class="holding-change ${change<0?'negative':'positive'}">${changes.length?t('Biến động tháng gần nhất','Latest monthly change')+': '+(change>=0?'+':'')+money(change):t('Chưa có cập nhật tháng','No monthly update yet')}</div><div class="holding-meta"><span>${p.locked?t('Khóa bán trong chặng','Locked during stage'):t('Có thể bán','Sellable')}</span>${p.debt>0?`<span>${t('Nợ','Debt')}: ${money(p.debt)} · ${t('Kỳ tới','Next due')}: ${money(p.payment)}</span>`:''}${cash>0?`<span>${t('Tiền chia tháng','Monthly distribution')}: +${money(cash)}</span>`:''}</div></article>`;}).join('')}</div>`:`<p class="holdings-empty">${t('Chưa có khoản đầu tư. Chọn ô Cơ hội hoặc quản lý vốn để bắt đầu.','No investments yet. Explore an Opportunity or use money management to begin.')}</p>`}<small>${t('Giá trị gộp trước khi trừ nợ. Biến động là cập nhật tháng gần nhất, không phải tổng lãi/lỗ từ lúc mua.','Gross values before debt. Changes reflect the latest monthly update, not total profit/loss since purchase.')}</small></section>`;
}
export function compactFinancialDashboard(s,lang='vi'){
 const vi=lang==='vi',t=(a,b)=>vi?a:b,m=financialModel(s),f=m.f;
 return `<aside class="finance-compact ${m.tone}" aria-label="${t('Dòng tiền và danh mục cạnh bàn cờ','Cash flow and holdings beside the board')}"><div class="compact-heading"><p class="eyebrow">${t('TÀI CHÍNH CỦA BẠN','YOUR FINANCES')}</p><span>${t('USD giả lập','Simulated USD')}</span></div><div class="compact-liquidity"><span>${t('Tiền dùng ngay','Available cash + reserve')}</span><strong>${money(m.liquid)}</strong><small>${t('Tiền mặt','Cash')} ${money(f.cash)} · ${t('Dự phòng','Reserve')} ${money(f.reserve)}</small></div><div class="compact-risk" role="status">${m.finished?t('Đã kết thúc chặng','Stage finished'):m.after<0?t('Thiếu tiền cho nghĩa vụ tháng tới','Next month is underfunded'):m.cashAfter<0?t('Có thể cần dùng dự phòng tháng tới','Next month may draw on reserves'):m.reserveMonths<1?t('Dự phòng dưới 1 tháng','Less than one month in reserve'):t('Theo dõi dự phòng và nghĩa vụ','Monitor reserves and obligations')} · ${m.reserveMonths.toFixed(1)} ${t('tháng dự phòng','reserve months')}</div><div class="finance-mini-cards"><section class="compact-flow"><h3>${m.finished?t('Kết quả chặng','Stage position'):t('Dòng tiền tháng','Cash flow — month')+' '+m.month}</h3><dl><div><dt>${t('Lương dự kiến','Expected salary')}</dt><dd>+${money(m.income)}</dd></div><div><dt>${t('Sinh hoạt + bắt buộc + trả góp','Living + charges + installments')}</dt><dd>−${money(m.due)}</dd></div><div class="${m.income-m.due<0?'negative':'positive'}"><dt>${t('Dòng tiền thuần đã biết','Known net cash flow')}</dt><dd>${money(m.income-m.due)}</dd></div><div class="flow-total"><dt>${t('Còn sau nghĩa vụ','After known obligations')}</dt><dd>${money(m.after)}</dd></div></dl><details><summary>${t('Chi tiết nghĩa vụ & cách tính','Obligation breakdown & calculation')}</summary><p>${t('Sinh hoạt','Living')}: ${money(m.living)} · ${t('Chi bắt buộc','Charges')}: ${money(m.pressure)} · ${t('Trả góp','Installments')}: ${money(m.installments)}.</p><p>${t('Chưa cộng thu nhập không chắc chắn, chưa trừ biến cố bất ngờ. Vốn đầu tư không được tính là tiền dùng ngay.','Excludes uncertain income and unexpected costs. Investments are not immediately available cash.')}</p></details></section>${portfolioDetails(s,lang)}</div><details class="finance-chart-detail"><summary>${t('Biểu đồ tài sản & thanh khoản','Wealth & liquidity chart')}</summary>${financeChart(s,lang)}</details></aside>`;
}
